package dev.jeka.core.api.utils;

/**
 * Utility class to deal with {@link Throwable}
 */
public final class JkUtilsThrowable {

    private JkUtilsThrowable() {
        // prevent instantiation
    }

    /**
     * Returns the specified exception itself if it is an unchecked exception
     * (extending {@link RuntimeException}).
     * 
     * @param exception the exception to check
     * @return the exception if it is unchecked, otherwise null
     */
    public static Throwable getUncheckedException(Throwable exception) {
        return exception instanceof RuntimeException ? exception : null;
    }

    /**
     * Returns the specified exception itself if it is a checked exception
     * (not extending {@link RuntimeException}).
     * 
     * @param exception the exception to check
     * @return the exception if it is checked, otherwise null
     */
    public static Throwable getCheckedException(Throwable exception) {
        return exception instanceof Exception && !exception.isInstance(RuntimeException.class) ? exception : null;
    }
}

