public class UpdateableFuture<T> extends AbstractFuture<T> {

    private final ListenableFuture<?> linkedFuture;

    public UpdateableFuture(ListenableFuture<?> linkedFuture) {
        this.linkedFuture = linkedFuture;
    }

    @Override
    public boolean set(T value) {
        return linkedFuture.set(value);
    }

    @Override
    public boolean setException(Throwable throwable) {
        return linkedFuture.setException(throwable);
    }

    /**
     * Marks this future as completed with the value of the linked future.
     *
     * @return The value of the linked future.
     */
    public T get() throws ExecutionException {
        return (T) linkedFuture.get();
    }

    /**
     * Updates the value of this future to the value of the linked future.
     *
     * @param value
