    }

    /**
     * Pops the last saved directory from directory stack and changes the current working directory to that directory
     * @param shellState is the state of JShell program
     * @param arguments is list of arguments that were passed along with command
     * (no arguments expected)
     * 
     * @throws Exception if directory stack is empty
