 * A concurrent property for an object.
 */
public class ConcurrentObjectProperty<T> extends SimpleObjectProperty<T>
{
    private final Object lock = new Object();

    /**
     * Creates a new concurrent object property.
     *
     * @param initialValue the initial value of the property.
     */
    public ConcurrentObjectProperty(T initialValue)
    {
        super(initialValue);
    }

    @Override
    protected void protectedSet(T value)
    {
        synchronized (lock)
        {
            super.set(value);
        }
    }

    @Override
